export const initWebSocket=(e)=>{const t=document.getElementById("openconnection");t.addEventListener("click",(function(){try{const t=new WebSocket(e);t.onopen=()=>{console.log("WebSocket connection established!")},t.onmessage=(e)=>{console.log("Message received:",e.data)},t.onerror=(e)=>{console.error("WebSocket error:",e)},t.onclose=()=>{console.log("WebSocket connection closed!")}}catch(e){window.console.error("Error initializing WebSocket:",e)}}))};